if (element.dataset.lightboxSetup === 'true') return;
element.dataset.lightboxSetup = 'true';
element.style.cursor = 'pointer';
element.style.position = element.style.position || 'relative';

const img = element.querySelector('img.thumbimage, img.mw-file-element');
let highResUrl = '';
let captionText = '';

if (img) {
  const src = img.src || img.dataset.src || '';
  const imageKey = img.dataset.imageKey || '';
  if (src && src.includes('/scale-to-width-down/')) {
    highResUrl = src.split('/scale-to-width-down/')[0] + '/revision/latest' + (src.includes('?') ? '?' + src.split('?')[1] : '');
  } else if (src) {
    highResUrl = src;
  }

  const lightboxCaption = element.closest('.wikia-gallery-item')?.querySelector('.lightbox-caption');
  const thumbcaption = element.closest('figure.thumb')?.querySelector('.thumbcaption .caption');
  captionText = (lightboxCaption ? lightboxCaption.textContent.trim() : '') ||
                (thumbcaption ? thumbcaption.textContent.trim() : '') ||
                (img.alt ? img.alt : '');
}

element.addEventListener('click', function(e) {
  e.preventDefault();
  e.stopPropagation();

  if (document.querySelector('.tutorial-lightbox-overlay')) return;

  const overlay = document.createElement('div');
  overlay.className = 'tutorial-lightbox-overlay';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-label', captionText || 'Tutorial screenshot');
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(0,0,0,0.85);z-index:999999;display:flex;align-items:center;justify-content:center;flex-direction:column;padding:20px;box-sizing:border-box;animation:lightboxFadeIn 0.2s ease;';

  const container = document.createElement('div');
  container.style.cssText = 'position:relative;max-width:95vw;max-height:85vh;display:flex;flex-direction:column;align-items:center;';

  const closeBtn = document.createElement('button');
  closeBtn.innerHTML = '&times;';
  closeBtn.style.cssText = 'position:absolute;top:-12px;right:-12px;width:40px;height:40px;border-radius:50%;background:#fff;color:#333;font-size:28px;font-weight:bold;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;z-index:10;box-shadow:0 2px 8px rgba(0,0,0,0.4);transition:transform 0.15s,background 0.15s;line-height:1;';
  closeBtn.addEventListener('mouseenter', () => { closeBtn.style.transform = 'scale(1.1)'; closeBtn.style.background = '#f0f0f0'; });
  closeBtn.addEventListener('mouseleave', () => { closeBtn.style.transform = 'scale(1)'; closeBtn.style.background = '#fff'; });
  closeBtn.addEventListener('click', () => overlay.remove());

  const imgEl = document.createElement('img');
  imgEl.src = highResUrl || (img ? img.src : '');
  imgEl.alt = captionText;
  imgEl.style.cssText = 'max-width:95vw;max-height:75vh;object-fit:contain;border-radius:8px;box-shadow:0 4px 24px rgba(0,0,0,0.6);background:#1a1a1a;';
  imgEl.onerror = function() {
    this.src = img ? img.src : '';
  };

  const captionBar = document.createElement('div');
  captionBar.style.cssText = 'margin-top:16px;padding:14px 24px;background:rgba(255,255,255,0.95);color:#222;border-radius:8px;max-width:700px;text-align:center;font-size:15px;line-height:1.5;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;box-shadow:0 2px 12px rgba(0,0,0,0.3);';
  captionBar.textContent = captionText;

  container.appendChild(closeBtn);
  container.appendChild(imgEl);
  if (captionText) {
    container.appendChild(captionBar);
  }
  overlay.appendChild(container);

  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) overlay.remove();
  });

  document.addEventListener('keydown', function handler(e) {
    if (e.key === 'Escape') {
      overlay.remove();
      document.removeEventListener('keydown', handler);
    }
  });

  document.body.appendChild(overlay);
});

if (element.dataset.hoverSetup === 'true') return;
element.dataset.hoverSetup = 'true';

const styleId = 'tutorial-lightbox-styles';
if (!document.getElementById(styleId)) {
  const style = document.createElement('style');
  style.id = styleId;
  style.textContent = `
    @keyframes lightboxFadeIn { from { opacity: 0; } to { opacity: 1; } }
    .wikia-gallery-item .gallery-image-wrapper:hover,
    figure.thumb .mw-file-description:hover {
      outline: 3px solid #4a90d9 !important;
      outline-offset: 2px !important;
      transition: outline 0.15s ease !important;
    }
    .tutorial-lightbox-overlay img:hover {
      transform: scale(1.02);
      transition: transform 0.2s ease;
    }
  `;
  document.head.appendChild(style);
}
